// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    Attacker att;

    function setUp() public {
        c = new Reentrance();
        att = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1e18);
        vm.deal(address(att), amount);

        att.deposit{value: amount}();
        att.pull();

        // General rule: withdrawing pays out exactly the recorded balance exactly once,
        // and leaves the account empty.
        assertTrue(att.totalReceived() == amount && c.getBalance(address(att)) == 0);
    }
}

contract Attacker {
    Reentrance c;
    uint256 total;
    bool entered;

    constructor(Reentrance _c) {
        c = _c;
    }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    function pull() external {
        c.withdrawBalance();
    }

    receive() external payable {
        total += msg.value;
        if (!entered) {
            entered = true;
            c.withdrawBalance();
        }
    }

    function totalReceived() external view returns (uint256) {
        return total;
    }
}
